import os, re, collections

decls = []  # (name, path, pkgdir, is_method)
for root, dirs, files in os.walk('internal'):
    for f in files:
        if not f.endswith('.go') or f.endswith('_test.go'): continue
        p = os.path.join(root, f)
        for i, line in enumerate(open(p, encoding='utf8', errors='ignore'), 1):
            m = re.match(r'func (?:\(([^)]*)\)\s*)?([A-Za-z_]\w*)\(', line)
            if m:
                decls.append((m.group(2), p, root, bool(m.group(1))))

# gather all go files (exclude tests, exclude proto/gen? keep all non-test)
gofiles = []
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in ('node_modules', '.git', 'web')]
    for f in files:
        if f.endswith('.go') and not f.endswith('_test.go'):
            gofiles.append(os.path.join(root, f))

contents = {p: open(p, encoding='utf8', errors='ignore').read() for p in gofiles}

results = []
for name, path, pkgdir, is_method in decls:
    pat = re.compile(r'(?<![\w.])(?:[\w]+\.)?' + re.escape(name) + r'\s*\(')
    total = 0
    callers = collections.Counter()
    for p, c in contents.items():
        n = len(pat.findall(c))
        if p == path:
            n -= 1  # its own declaration
        if n > 0:
            total += n
            callers[p] = n
    results.append((total, name, path, is_method, callers))

results.sort(reverse=True, key=lambda x: x[0])
for total, name, path, is_method, callers in results[:25]:
    print(total, name, path, 'method' if is_method else 'func')
    for p, n in callers.most_common(6):
        print('    ', p, n)
EOF
