use strict; use warnings;
use File::Find;

my (@decls, @gofiles);
find(sub {
  return unless /\.go$/ && !/_test\.go$/;
  my $p = $File::Find::name; $p =~ s{^\./}{};
  push @decls, [$p];
}, 'internal');

my %declmap;
for my $d (@decls) {
  my $p = $d->[0];
  open my $fh, '<', $p or next;
  while (my $l = <$fh>) {
    if ($l =~ /^func\s+(\(([^)]*)\)\s*)?([A-Za-z_]\w*)\s*\(/) {
      my $name = $3; my $recv = $2 // '';
      $declmap{"$name\t$p\t" . ($recv ? 'method' : 'func')} = 1;
    }
  }
  close $fh;
}

find(sub {
  return unless /\.go$/ && !/_test\.go$/;
  my $p = $File::Find::name; $p =~ s{^\./}{};
  return if $p =~ m{^(node_modules|web)/};
  push @gofiles, $p;
}, '.');

my %content;
for my $p (@gofiles) { open my $fh,'<',$p or next; local $/; $content{$p} = <$fh>; close $fh; }

my @res;
for my $key (keys %declmap) {
  my ($name, $path, $kind) = split /\t/, $key;
  my $total = 0; my %callers;
  my $re = qr/(?<![\w.])(?:\w+\.)?\Q$name\E\s*\(/;
  for my $p (@gofiles) {
    my $c = $content{$p} // '';
    my $n = () = $c =~ /$re/g;
    $n-- if $p eq $path;
    if ($n > 0) { $total += $n; $callers{$p} = $n; }
  }
  push @res, [$total, $name, $path, $kind, {%callers}];
}
@res = sort { $b->[0] <=> $a->[0] } @res;
for my $r (@res[0..24]) {
  last unless $r;
  printf "%d  %s  %s  %s\n", $r->[0], $r->[1], $r->[2], $r->[3];
  my $c = $r->[4];
  my @top = sort { $c->{$b} <=> $c->{$a} } keys %$c;
  for my $p (@top[0..4]) { last unless $p; printf "      %s %d\n", $p, $c->{$p}; }
}
EOF
